import re
from typing import Dict, Any

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.splitlines()

    raw_sections: Dict[str, Dict[str, str]] = {}
    current_section = None
    pending_key = None
    pending_value = None

    def strip_comment(line: str) -> str:
        """Remove inline comment if present, respecting quotes."""
        inside_quote = False
        for i, ch in enumerate(line):
            if ch == '"':
                if not inside_quote:
                    inside_quote = True
                else:
                    inside_quote = False
            elif ch in ';#' and not inside_quote:
                if i > 0 and line[i-1].isspace():
                    return line[:i]          # cut before the comment marker
        return line

    for raw_line in lines:
        # Rule 3: ignore empty or comment-start lines
        stripped_raw = raw_line.lstrip()
        if not stripped_raw or stripped_raw[0] in ';#':
            continue

        clean_line = strip_comment(raw_line)

        # Check for section header first
        if clean_line.startswith('[') and clean_line.endswith(']'):
            # finalize pending key if any
            if pending_key is not None and current_section is not None:
                if current_section not in raw_sections:
                    raw_sections[current_section] = {}
                raw_sections[current_section][pending_key] = pending_value
                pending_key = None
                pending_value = None
            # section name (do not trim inside)
            name = clean_line[1:-1]
            current_section = name
            if current_section not in raw_sections:
                raw_sections[current_section] = {}
            continue

        # Check for continuation line
        if pending_key is not None and current_section is not None and clean_line.startswith((' ', '\t')):
            # continuation: append stripped text with newline
            stripped_text = clean_line.strip()
            pending_value += "\n" + stripped_text
            continue

        # Otherwise, key line (must be inside a section)
        if current_section is None:
            # key line before any section -> ValueError
            raise ValueError("Key line before any section header")

        # Find first '=' or ':' outside quotes
        inside_quote = False
        found_sep = None
        sep_char = None
        for i, ch in enumerate(clean_line):
            if ch == '"':
                if not inside_quote:
                    inside_quote = True
                else:
                    inside_quote = False
            elif ch in '=:' and not inside_quote:
                if found_sep is None:
                    found_sep = i
                    sep_char = ch

        if found_sep is None:
            # malformed key line
            raise ValueError("Malformed key line: missing separator outside quotes")

        key_part = clean_line[:found_sep]
        value_part = clean_line[found_sep+1:]

        key_raw = key_part.strip()
        if not key_raw:
            raise ValueError("Empty key")
        key = key_raw.lower()

        # Process value part (remove surrounding quotes)
        val = value_part.strip()
        if val.startswith('"') and val.endswith('"') and len(val) >= 2:
            val = val[1:-1]

        # Finalize previous pending key if exists
        if pending_key is not None:
            if current_section not in raw_sections:
                raw_sections[current_section] = {}
            raw_sections[current_section][pending_key] = pending_value
            pending_key = None
            pending_value = None

        # Start new pending key
        pending_key = key
        pending_value = val

    # Finalize pending key after loop
    if pending_key is not None and current_section is not None:
        if current_section not in raw_sections:
            raw_sections[current_section] = {}
        raw_sections[current_section][pending_key] = pending_value

    # Interpolation resolution
    cache: Dict[tuple[str, str], str] = {}
    visiting: set[tuple[str, str]] = set()

    def substitute(value: str, section_name: str) -> str:
        """Replace ${...} placeholders in value that are outside quotes."""
        # simple scan, assuming no quotes inside value after quote removal
        # (spec says quoted values keep everything inside quotes exactly,
        # so we do not substitute inside quotes; but we have already removed
        # outer quotes, so remaining value should not contain quotes that delimit)
        i = 0
        n = len(value)
        out = []
        while i < n:
            if value[i] == '$' and i + 1 < n and value[i+1] == '{':
                j = i + 2
                while j < n and value[j] != '}':
                    j += 1
                if j == n:
                    raise KeyError(f"Unterminated placeholder at position {i}")
                content = value[i+2:j]
                i = j + 1
                # parse content
                if ':' in content:
                    # ${section:key}
                    parts = content.split(':', 1)
                    ref_section = parts[0]
                    ref_key = parts[1]
                else:
                    # ${key}
                    ref_section = None
                    ref_key = content

                try:
                    if ref_section is None:
                        # same section: look in own dict first, then DEFAULT
                        if ref_key in raw_sections[section_name]:
                            res_section = section_name
                            res_key = ref_key
                        elif "DEFAULT" in raw_sections and ref_key in raw_sections["DEFAULT"]:
                            res_section = "DEFAULT"
                            res_key = ref_key
                        else:
                            raise KeyError(f"Key {ref_key} not found in section {section_name} or DEFAULT")
                    else:
                        # other section: must exist and key must be in that section
                        if ref_section not in raw_sections:
                            raise KeyError(f"Section {ref_section} not defined")
                        if ref_key in raw_sections[ref_section]:
                            res_section = ref_section
                            res_key = ref_key
                        else:
                            raise KeyError(f"Key {ref_key} not found in section {ref_section}")
                except KeyError as e:
                    raise KeyError(str(e))
                # resolve recursively
                try:
                    resolved_ref = resolve_key(res_section, res_key)
                except ValueError as ve:
                    raise ValueError(str(ve))
                except KeyError as ke:
                    raise ke
                out.append(resolved_ref)
            else:
                out.append(value[i])
                i += 1
        return ''.join(out)

    def resolve_key(section_name: str, key: str) -> str:
        key_pair = (section_name, key)
        if key_pair in cache:
            return cache[key_pair]
        if key_pair in visiting:
            raise ValueError("Interpolation cycle detected")
        visiting.add(key_pair)
        raw_val = raw_sections[section_name][key]
        resolved_val = substitute(raw_val, section_name)
        visiting.remove(key_pair)
        cache[key_pair] = resolved_val
        return resolved_val

    # Resolve all keys (including DEFAULT)
    for sec, sec_dict in raw_sections.items():
        for key in sec_dict:
            try:
                resolve_key(sec, key)
            except (KeyError, ValueError) as e:
                # re-raise to propagate
                raise e

    # Build output excluding DEFAULT
    output: Dict[str, Dict[str, str]] = {}
    for sec, sec_dict in raw_sections.items():
        if sec == "DEFAULT":
            continue
        out_dict = {}
        for key in sec_dict:
            # retrieve resolved value from cache
            resolved = cache[(sec, key)]
            out_dict[key] = resolved
        output[sec] = out_dict

    return output
