def parse_duration(s: str) -> int:
    if not s.strip():
        raise ValueError()
    n = len(s)
    i = 0
    last_unit_num = None
    used_units = set()
    parts = []
    while i < n:
        # Skip whitespace
        while i < n and s[i].isspace():
            i += 1
        if i == n:
            break
        if s[i] in '0123456789':
            j = i
            while j < n and s[j] in '0123456789':
                j += 1
            num_str = s[i:j]
            val = int(num_str)
            if j == n:
                # Number without unit
                raise ValueError()
            ch = s[j]
            unit_lower = ch.lower()
            if unit_lower not in ('h', 'm', 's'):
                raise ValueError()
            if unit_lower in used_units:
                raise ValueError()
            unit_num = {'h': 0, 'm': 1, 's': 2}[unit_lower]
            if last_unit_num is not None and unit_num < last_unit_num:
                raise ValueError()
            parts.append((val, unit_num))
            used_units.add(unit_lower)
            last_unit_num = unit_num
            i = j + 1
        else:
            raise ValueError()
    total = 0
    for val, unit_num in parts:
        if unit_num == 0:
            total += val * 3600
        elif unit_num == 1:
            total += val * 60
        else:
            total += val
    return total
