import unicodedata

def slugify(title: str, max_len: int = 50) -> str:
    # Step 1: transliterate accented characters to ASCII, drop other non-ASCII
    normalized = unicodedata.normalize('NFKD', title)
    ascii_str = ''.join(ch for ch in normalized if ord(ch) < 128)

    # Step 2: lowercase
    lowered = ascii_str.lower()

    # Step 3: extract words (a-z and 0-9) and join with hyphens
    words = []
    cur = []
    for ch in lowered:
        if ('a' <= ch <= 'z') or ('0' <= ch <= '9'):
            cur.append(ch)
        else:
            if cur:
                words.append(''.join(cur))
                cur = []
    if cur:
        words.append(''.join(cur))
    slug = '-'.join(words)

    # Already within limit?
    if len(slug) <= max_len:
        return slug

    # Step 4: truncate without cutting words
    words_slug = slug.split('-')
    first_len = len(words_slug[0])
    if first_len > max_len:
        # hard‑cut the first word
        return words_slug[0][:max_len]

    accumulated = []
    current_len = 0
    for w in words_slug:
        if not accumulated:
            accumulated.append(w)
            current_len = len(w)
        else:
            if current_len + 1 + len(w) <= max_len:
                accumulated.append(w)
                current_len += 1 + len(w)
            else:
                break
    return '-'.join(accumulated)
